import mdx from "@astrojs/mdx";
import { defineConfig } from "astro/config";
import * as babel from "@babel/core";
import stylexOptions from "./stylex.config.cjs";

// Compile stylex.create/defineVars calls in .ts style modules to static class
// maps. The CSS itself is generated by @stylexjs/postcss-plugin (see
// postcss.config.cjs), which must use the same options (stylex.config.cjs).
function stylexTransform() {
  return {
    name: "stylex-babel-transform",
    enforce: "pre",
    async transform(code, id) {
      const [filename] = id.split("?");
      if (!/\.(ts|tsx|js|jsx|mjs)$/.test(filename)) return;
      if (filename.includes("node_modules")) return;
      if (!code.includes("@stylexjs/stylex")) return;
      const result = await babel.transformAsync(code, {
        filename,
        babelrc: false,
        configFile: false,
        presets: ["@babel/preset-typescript"],
        plugins: [["@stylexjs/babel-plugin", stylexOptions]],
        sourceMaps: true,
      });
      if (!result?.code) return;
      return { code: result.code, map: result.map };
    },
  };
}

// open external links in a new tab, no dependency needed
function externalLinks() {
  return (tree) => {
    const visit = (node) => {
      if (node.type === "element" && node.tagName === "a") {
        const href = node.properties?.href;
        if (typeof href === "string" && /^https?:\/\//.test(href)) {
          node.properties.target = "_blank";
          node.properties.rel = ["noopener", "noreferrer"];
        }
      }
      node.children?.forEach(visit);
    };
    visit(tree);
  };
}

export default defineConfig({
  // override per environment (e.g. preview deployments) at build time
  site: process.env.SITE_URL ?? "https://chronark.com",
  prefetch: true,
  integrations: [mdx()],
  vite: {
    plugins: [stylexTransform()],
  },
  markdown: {
    rehypePlugins: [externalLinks],
    shikiConfig: {
      themes: {
        light: "github-light",
        dark: "github-dark",
      },
    },
  },
});
